import "server-only";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { eq } from "drizzle-orm";
import { db } from "@/server/db";
import { storedFiles } from "@/server/db/schema";

/*
 * File store. Keys are generated by the server, never taken from user input.
 * - disk (default): files under STORAGE_DIR; back the directory up with the database.
 * - database: rows in `stored_files`, for hosts without a persistent disk (Vercel).
 */
const driver = process.env.STORAGE_DRIVER === "database" ? "database" : "disk";

// turbopackIgnore: the directory is runtime configuration, not part of the build.
const root = path.resolve(/* turbopackIgnore: true */ process.env.STORAGE_DIR || "storage");

function resolveKey(key: string) {
  const full = path.resolve(/* turbopackIgnore: true */ root, key);
  if (!full.startsWith(root + path.sep)) throw new Error("Invalid storage key");
  return full;
}

export async function putFile(key: string, data: Buffer) {
  if (driver === "database") {
    // The primary key rejects a second write to the same key.
    await db.insert(storedFiles).values({ key, data });
    return;
  }
  const full = resolveKey(key);
  await mkdir(/* turbopackIgnore: true */ path.dirname(full), { recursive: true });
  // "wx": never overwrite an existing file.
  await writeFile(/* turbopackIgnore: true */ full, data, { flag: "wx", mode: 0o600 });
}

export async function getFile(key: string): Promise<Buffer> {
  if (driver === "database") {
    const [row] = await db.select({ data: storedFiles.data }).from(storedFiles).where(eq(storedFiles.key, key));
    if (!row) throw new Error("File not found");
    return Buffer.from(row.data);
  }
  return readFile(/* turbopackIgnore: true */ resolveKey(key));
}
